import{i as $,C as a,d as i,c as h}from"./fleetCanonical-D-0FIFMD.js";import{f as p,b as x}from"./pricing-wamygKtF.js";import{g as y}from"./guideMeta-BnZ1ttPl.js";import{a5 as b,b as q,i as P}from"./index-vhM5FyyC.js";const g="2026-09-04",D=["premium-suv-scottsdale","maybach-shuttle-sprinter-8","maybach-jet-sprinter-scottsdale","executive-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","limo-sprinter-16-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"].filter($),o=D.map(e=>({slug:e,name:a[e],capacity:i[e],hourlyRateCents:h[e].hourlyRateCents,minimumHours:h[e].minimumHours}));function d(e){return p(h[e].hourlyRateCents)}function u(e,t,n){return p(Math.round(h[e].hourlyRateCents*t/n))}function z(e,t){const n=h[e];return p(n.hourlyRateCents*x(t,n.minimumHours))}const v=5,f=["ultra-luxury-party-sprinter-scottsdale","pink-hummer-limo","party-bus-28-scottsdale"];function I(){const e=f.map(r=>{const C=r==="pink-hummer-limo"?", and it does no airport pickups":"";return`The ${a[r]} seats ${i[r]} at ${d(r)} an hour${C}.`}),t=f.map(r=>h[r].minimumHours),n=new Set(t).size===1?`Each has a ${t[0]}-hour minimum.`:`Minimums are ${f.map(r=>`${h[r].minimumHours} hours in the ${a[r]}`).join(", ")}.`,s=k[0];return`Wherever you stay, book one vehicle for the big night. ${e.join(" ")} ${n} A ${v}-hour booking in the ${a[s.slug]}, the ${s.guests}-guest row in the table on this page, is ${z(s.slug,v)} before tax.`}const k=[{guests:8,slug:"executive-sprinter-scottsdale"},{guests:12,slug:"limo-sprinter-13-scottsdale"},{guests:15,slug:"limo-sprinter-16-scottsdale"},{guests:16,slug:"limo-sprinter-16-scottsdale"},{guests:25,slug:"party-bus-28-scottsdale"}],l=k.map(({guests:e,slug:t})=>({guests:e,name:a[t],seats:i[t],rate:d(t),each:u(t,5,e)})),E=[{href:"/services/wedding-transportation-scottsdale",label:"Scottsdale wedding transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport group transportation"},{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published hourly pricing"}];function W(e){return/^The\s/.test(e)?e:/^[AEIOU]/i.test(e)?`An ${e}`:`A ${e}`}function m(e){return/^The\s/.test(e)?e:`the ${e}`}function O(e){return/^The\s/.test(e)?e:/^[AEIOU]/i.test(e)?`an ${e}`:`a ${e}`}function c(e){const t=o.find(s=>s.slug==="executive-sprinter-scottsdale"),n=o.find(s=>s.slug==="motorcoach-56");return{path:e.path,title:`${e.name} Wedding Shuttle Guide | Scottsdale Sprinters`,description:`Plan ${e.name} wedding shuttles with published vehicle capacities, hotel pickup waves, venue arrival coordination, and an end-of-night return plan.`,metaDescription:"Hotel pickup waves, vehicle sizing and the end-of-night return",updatedAt:"2026-09-18",h1:`${e.name} wedding shuttle and guest transportation`,eyebrow:"Wedding venue transportation guide",intro:`${W(e.name)} shuttle from Scottsdale Sprinters works best when one transportation lead owns the guest list, every pickup has a written address, and the venue confirms the final arrival point. This guide turns that into vehicle counts, pickup waves, driver notes, and a return schedule, without inventing a gate or loading zone.`,fleetTable:!0,sections:[{heading:`What should couples know about ${e.name} before planning transportation?`,answer:`${e.name} planning starts with 3 verified details: the venue address, the contracted event space, and the arrival instructions supplied by the venue team, because a property name alone is not enough for a driver brief and public websites do not always publish a wedding-specific loading point.`,paragraphs:[`${e.name} is at ${e.address}. ${e.venueFacts} That tells a transportation planner where the property is and what kind of celebration the venue supports, but it does not replace the instructions in the couple's venue contract. The final driver sheet should use the venue's current written directions and the event-space name exactly as the coordinator provides them.`,`${e.arrivalNote} We do not label an unverified driveway, gate, porte cochere, or service entrance as the wedding drop-off. The couple or planner should ask the venue which approach is approved for the booked space, whether a vehicle may wait, and where guests with mobility needs should be delivered. Those answers belong in the dispatch note before the wedding day.`,e.venueSpecific[0],"Treat the venue source linked below as a planning reference, then reconcile it with the banquet event order. Websites can change, private-event operations can differ from hotel arrivals, and another event may affect traffic flow. One confirmed instruction shared with the reservations team, planner, and venue contact is safer than several guests forwarding different map pins."]},{heading:`Which vehicle size fits ${m(e.name)} wedding guest count?`,answer:`For ${e.name}, use 10 published capacity bands from a 6-passenger luxury SUV through a 56-passenger motorcoach, then reserve seats for the people actually riding rather than the total attendance; a 120-guest reception may need transportation for only 42 hotel guests while the wedding party follows a separate schedule.`,paragraphs:[`The table on this page uses the same current capacities and hourly rates shown with each vehicle. The ${t.name} seats ${t.capacity} and starts at ${p(t.hourlyRateCents)} per hour, while the ${n.name} seats ${n.capacity} and starts at ${p(n.hourlyRateCents)} per hour. Those figures update with the published fleet information rather than relying on estimates copied into the article.`,"Build the rider count from RSVPs, hotel blocks, family assignments, and accessibility needs. Do not divide the full invitation list by the largest vehicle. Some guests will drive, some will stay on property, and some may need an earlier departure. A clean manifest groups people by pickup and return wave, which can reduce empty seats without putting the ceremony at risk.",e.venueSpecific[1],"Leave operational margin. A vehicle advertised for a maximum seated capacity is not a promise that every combination of passengers, dresses, mobility devices, gifts, and personal items will fit comfortably. Tell the reservations team what the group is carrying. Luggage and gear fit should be confirmed separately whenever airport arrivals, welcome bags, decor, or vendor materials are part of the ride."]},{heading:`How should hotel pickup waves for ${e.name} be organized?`,answer:`Plan at least 2 pickup waves for ${e.name} when guests are split across hotels or readiness times: an early family and wedding-party movement with schedule padding, followed by the main guest shuttle, while one named transportation lead confirms each vehicle's manifest instead of asking chauffeurs to reconcile a changing group chat.`,paragraphs:[`${e.hotelPlan} Start with exact hotel names and street addresses, because similarly named Scottsdale resorts can appear in search results. List a lobby contact for each property and tell guests whether they should wait inside or at a venue-approved pickup point. A chauffeur should never have to circle a resort while a guest finishes packing upstairs.`,"For each wave, publish one ready time and one departure time. The ready time is when guests are fully dressed, carrying everything they need, and physically present at the pickup point. The departure time is when the vehicle rolls. Put buffer between that departure and the ceremony's guest-seating deadline, not merely the invitation time, so normal loading and traffic variation do not consume the entire margin.",e.venueSpecific[2],"A transportation lead should check names against the manifest, call the designated guest contact when someone is missing, and make the go-or-hold decision. That role should not sit with the couple. Share the lead's number with the reservations team before service and choose a backup who can answer while the primary person is in the ceremony."]},{heading:`Where should a shuttle drop guests at ${e.name}?`,answer:`Use 1 venue-confirmed arrival point for each scheduled wave, written exactly as ${m(e.name)} event team provides it; where the venue publishes no wedding shuttle lane we confirm the live one with them instead of naming a gate, because a guessed entrance sends a full vehicle into the wrong traffic pattern.`,paragraphs:["Send the venue the vehicle type, approximate length, arrival window, and number of passengers. Ask whether the vehicle may dwell while guests unload, whether a coordinator will meet it, and whether the same point is used after the reception. If the answer changes by event space or time of day, place both instructions in the schedule with a clear effective time.","The chauffeur follows current property signage, traffic staff, and venue instructions on arrival. A static web guide cannot see a temporary barricade, private event, construction change, or emergency route. Guests should remain seated until the vehicle is in the approved unloading position, then move together toward the venue contact instead of scattering across a drive.",e.venueSpecific[3],"For older guests or anyone using a mobility device, ask the venue about its accessible route before assigning the vehicle. Vehicle capacity and property accessibility are different questions. Tell the reservations team about boarding needs early so the proposed fleet can be checked; never assume that a capacity number by itself confirms an accessible boarding setup."]},{heading:`How should ${e.name} wedding groups use separate movements?`,answer:`Separate ${O(e.name)} wedding day into 3 manifests when schedules differ: wedding party, immediate family, and general guests, because one all-purpose shuttle can be delayed by portraits or pre-ceremony duties while another group still needs to reach its seating time, hotel, rehearsal meal, or reception entrance.`,paragraphs:["The wedding party often carries garments, flowers, personal items, and timing responsibilities that the general guest group does not. Give that vehicle a direct contact who understands photography and ceremony cues. If partners are getting ready at different locations, write each movement as its own trip rather than describing the day as a round trip with several implied stops.","Immediate family may need a later pre-ceremony pickup and an earlier return after formal photographs. General guests benefit from the simplest possible instruction: one pickup place, one ready time, and one venue arrival. Keeping those flows separate makes the service easier to understand and gives the planner a clean way to adjust one group without rewriting every rider's plan.",e.venueSpecific[4],"If the ceremony and reception are in different spaces on the same property, confirm whether guests walk or require a vehicle transfer. Do not assume the distance or route from a property map. If off-property movement is required, schedule it explicitly and verify that every guest who arrived by shuttle also has a seat for the next leg."]},{heading:`What is the best end-of-night return plan from ${e.name}?`,answer:`Schedule 2 or 3 return windows from ${e.name} instead of one final departure: an early option for families, a primary option after major reception moments, and a last sweep after the contracted end, with every rider told which hotels are served and who authorizes an unscheduled stop.`,paragraphs:["Return demand is rarely even. Some guests want to leave after dinner, while others stay through the final song. A single departure can either strand early riders or leave a vehicle idle for hours. Staggered waves give guests a clear choice and let the planner protect the final pickup without turning the chauffeur into an on-demand dispatcher.","Write a destination list for every return wave. If multiple hotels are served, order them before the day and tell guests that the shuttle is not a private car making individual address changes. The transportation lead should record anyone who switches waves so the final sweep does not wait for a guest who already left.",e.venueSpecific[5],"Confirm where the vehicle may wait and when it should approach the pickup point. At properties with active resort traffic, arriving too early can be as disruptive as arriving late. The driver and venue contact should have each other's current instructions through the transportation lead, while guests receive a simple meeting-place description approved by the venue."]},{heading:`When should ${e.name} wedding transportation be reserved?`,answer:`Availability varies by date and by vehicle, so no fixed lead time applies: build ${m(e.name)} plan in 3 passes — settle the service window and pickup addresses, freeze the first manifest once RSVPs are in, then send a final update after the venue confirms access — and we confirm in writing what is open.`,paragraphs:["The first conversation should cover date, service window, pickup addresses, approximate riders, venue, and the kind of experience the couple wants. The reservations team can then identify a sensible capacity mix. A quote is more useful when it describes actual movements than when it contains only a guest total and a broad request for a shuttle.","At the RSVP checkpoint, reconcile replies with hotel lists and identify children, mobility needs, bulky items, and guests who require the early return. Confirm the venue contact and event-space name. This is also the moment to test every phone number, eliminate duplicate guest names, and make sure the planner's schedule matches the transportation schedule.",e.venueSpecific[6],`The final update should be short: approved addresses, ready and departure times, rider counts, contact hierarchy, and venue instructions. Avoid sending a fresh narrative to the driver on the wedding morning. If a true change occurs, route it through the transportation lead and reservations team so there is one acknowledged version. ${b}`]},{heading:`How do couples request a precise ${e.name} shuttle quote?`,answer:`A useful ${e.name} quote request includes 7 items: event date, contracted space, every pickup address, first pickup time, final return time, rider count by wave, and a transportation contact; send those details plus special boarding considerations to the reservations team at ${q} or ${P}.`,paragraphs:["Published rates provide the starting point, but the right schedule still depends on time and routing. Tell the reservations team whether the vehicle remains with the group, returns for later waves, or performs only defined transfers. Mention any airport luggage, coolers, decor, mobility devices, or oversized personal items so fit can be confirmed before a vehicle is selected.",`Ask the venue for written transportation instructions and attach them to the request. For ${e.name}, include the contracted event space and the venue coordinator's name. If the venue has not yet finalized access, say that clearly; the quote can use a planning assumption while the final dispatch sheet waits for verified directions.`,e.venueSpecific[7],"Compare the proposed seat count with the manifest, not with a rounded attendance number. A slightly larger vehicle can simplify a wave, while two smaller vehicles can protect groups with different timelines. The best answer is the one that makes the schedule resilient and understandable, not automatically the vehicle with the lowest hourly rate."]},{heading:`What are the most common ${e.name} shuttle questions?`,answer:`Most ${e.name} plans come down to 4 questions: how many people are actually riding, which hotel or home each wave leaves from, what arrival point the venue approves, and how many return times guests need; the answers below give a practical starting point for the planner.`,paragraphs:[]}],faqs:[{question:`Can a shuttle wait at ${e.name} during the wedding?`,answer:`Waiting depends on the venue's current instructions, the contracted service plan, and available staging. Ask ${m(e.name)} event team where a vehicle may stand, then give that direction to the reservations team before dispatch.`},{question:"Should every invited guest receive a shuttle seat?",answer:"No. Count guests who commit to each pickup and return wave, then add operational margin. Guests staying on property or driving themselves should not inflate the vehicle count."},{question:"Can airport arrivals and the wedding shuttle use the same vehicle?",answer:"Sometimes, but only when flight timing, luggage fit, and the wedding schedule align. Keep airport movements separate on the itinerary so a delayed flight cannot quietly endanger a ceremony departure."},{question:"Who should communicate with the chauffeur?",answer:"Choose one transportation lead and one backup. The couple should not manage guest calls or access changes during portraits, the ceremony, or the reception."}],links:E,sources:[{label:e.sourceLabel,href:e.sourceUrl},...e.secondarySource?[e.secondarySource]:[]]}}const L=[c({path:"/guides/venues/el-chorro",name:"El Chorro",address:"5550 East Lincoln Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official weddings page presents multiple indoor and outdoor event spaces between Camelback and Mummy mountains.",arrivalNote:"The official site publishes the Lincoln Drive address but does not publish a named wedding-shuttle gate, so the exact unload point must come from the venue team.",hotelPlan:"Guests may be staying across Paradise Valley and Scottsdale rather than at the venue itself, so hotel consolidation matters.",sourceLabel:"El Chorro weddings and events",sourceUrl:"https://elchorro.com/weddings-and-events/",venueSpecific:["El Chorro identifies eight event spaces on its wedding materials, with indoor and outdoor choices between Camelback and Mummy mountains. Put the contracted space on every chauffeur note; the Lincoln Drive street address gets the vehicle to the property, but the space name gives the venue team the context needed to confirm the final approach.","Eight named spaces can support very different guest plans, so count riders for the actual ceremony and reception layout instead of treating El Chorro as one generic room. Ask whether the contracted spaces share an arrival area and whether guests move on foot between them before deciding that one capacity plan covers the entire celebration.","El Chorro is not a lodging property, so every guest who uses the shuttle begins somewhere else. Consolidate Paradise Valley and Scottsdale hotel riders into a small number of documented pickups, then keep private-home pickups separate when their timing or access instructions differ. This avoids turning the Lincoln Drive arrival into the first moment the manifest is reconciled.","For the Lincoln Drive approach, the useful venue answer is the approved wedding unload point for the contracted space, not a guessed entrance based on a public map. Give El Chorro the vehicle type and arrival window, record the response verbatim, and ask whether the same point remains available when the reception ends.","A wedding party assigned to one of El Chorro’s outdoor settings may have a different readiness cue from guests entering an indoor event space. Tie each manifest to a named coordinator cue and space, then state whether portraits occur before or after that movement. The chauffeur needs a departure instruction, not the entire photography schedule.","Return waves should name the destination hotels before the first vehicle approaches El Chorro. If guests are split between Paradise Valley and Scottsdale, group compatible stops and publish which wave serves each one. The last sweep should be tied to the contracted event end and the pickup instruction the venue confirms for that evening.","At the 14-day review, repeat the full El Chorro address and every contracted space name with the venue contact. Ask whether another event affects the approach, where the transportation lead should assemble riders, and when a vehicle may be called forward. Record changes in the final schedule rather than relying on an earlier email thread.","An El Chorro quote request is strongest when it names the eight-space choice actually booked, the hotel clusters, and the guest count for each direction. Include whether the ceremony and reception use different spaces and whether any passenger needs extra boarding time. Those details matter more than sending the reservations team the invitation total alone."]}),c({path:"/guides/venues/clayton-house",name:"The Clayton House",address:"3719 North 75th Street, Scottsdale, Arizona 85251",venueFacts:"The official tourism listing describes separate event rooms, covered patios, and in-house catering and bar service.",arrivalNote:"The official tourism listing publishes the 75th Street address but does not name a wedding-shuttle curb or gate; confirm the approved unloading position with the venue.",hotelPlan:"Downtown hotels may look close on a map, yet formalwear, weather, and traffic make a scheduled pickup more dependable than asking guests to improvise.",sourceLabel:"Clayton House official venue page",sourceUrl:"https://www.wedgewoodweddings.com/venues/clayton-house",venueSpecific:["The Clayton House describes two indoor-outdoor event spaces plus in-house catering and bar service at its 75th Street property. Name the booked space in the transportation schedule so the venue can distinguish the wedding movement from a general arrival, especially when both parts of the property may be active.","A public address does not establish a shuttle loading position. Treat directions and commercial passenger unloading as separate questions: send the proposed vehicle type to The Clayton House, ask where it should approach, and keep unused seats available when formalwear, gifts, or mobility equipment affect the practical load.","Downtown Scottsdale lodging can produce several small guest clusters. Combine riders by exact hotel and ready time instead of scheduling an individual stop for every room block. A concise route into 3719 North 75th Street gives the transportation lead a realistic headcount at each pickup and leaves the chauffeur with a clear final destination.","Use the published 75th Street address as the routing anchor, then obtain the event team’s exact unloading instruction. Do not infer that the parking entrance, a nearby curb, or the closest door is approved for a larger vehicle. The venue contact should also state whether guests can remain under cover while waiting for a return wave.","Because The Clayton House offers two indoor-outdoor spaces, confirm whether wedding-party portraits, family arrival, and general guest seating all begin from the same side of the property. If they do not, write separate movements and contacts. A single vehicle can still serve multiple groups, but only when each handoff is explicit.","Do not treat nearby public parking as permission for a chauffeured vehicle to stage through the reception. Ask where an empty vehicle may wait, if waiting is allowed, and how the transportation lead should call it forward. That answer determines whether early and final return waves use one continuous booking or separate movements.","During the final review, confirm the event-space name, 75th Street address, authorized approach, and end-of-night assembly point with The Clayton House. Downtown activity can change the practical route even when the street address stays the same, so the current venue instruction and live traffic direction belong on the final chauffeur sheet.","For a Clayton House quote, list each event room only if the wedding actually uses it. Include downtown hotel names, private-home stops, and return-wave destinations, then attach the venue’s loading response. This gives the reservations team enough detail to compare one larger vehicle with coordinated smaller vehicles without assuming that a public address solves shuttle access."]}),c({path:"/guides/venues/fairmont-scottsdale-princess",name:"Fairmont Scottsdale Princess",address:"7575 East Princess Drive, Scottsdale, Arizona 85255",venueFacts:"The official weddings page describes indoor and outdoor wedding settings and an on-property wedding planner.",arrivalNote:"Fairmont publishes driving directions that end at the lobby entrance; because a private event space may use different instructions, confirm whether the wedding shuttle should follow that public arrival route.",hotelPlan:"On-property guests and off-property guests need separate counts, and large resort grounds make the named event space especially important on the driver sheet.",sourceLabel:"Fairmont Scottsdale Princess weddings",sourceUrl:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/weddings.html",secondarySource:{label:"Fairmont location and public arrival directions",href:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/location-contact.html"},venueSpecific:["Fairmont’s public driving directions end with the lobby entrance on the right, while its wedding page describes multiple indoor and outdoor settings. Put both the contracted event space and the venue’s private-event arrival instruction on the schedule; a lobby route is useful context, but it is not automatically the wedding shuttle route.","Separate Fairmont guests staying at the resort from riders coming from other hotels or homes before choosing capacity. On-property guests may not need a seat for every movement, while an off-property party may need a fully assigned wave. The manifest should reflect committed riders rather than the total number of rooms or reception guests.","For an on-property resort wedding, the most important hotel-wave question is which guests are truly boarding off property. Give each outside hotel an exact lobby or approved pickup instruction, then create a separate note for any Fairmont guest who needs transportation within the wedding plan. Do not mix walkers into the shuttle count simply for symmetry.","Ask the Fairmont wedding planner whether the vehicle follows the published lobby approach or a different route for the contracted setting. Record the answer with the event-space name and arrival window. If staff direct the chauffeur elsewhere on the day, that current instruction controls and the transportation lead should update waiting guests before they move.","A wedding party using a Fairmont lawn or outdoor setting may have a different cue from guests entering a ballroom or other indoor space. Keep the getting-ready location and event-space name beside each movement. That prevents the driver sheet from reducing a large resort plan to the property address and one ambiguous arrival time.","For Fairmont return waves, identify which riders remain at the resort and which leave for off-property lodging. Publish only the destinations served by each departure. The transportation lead should assemble outbound guests at the venue-approved point and call the vehicle forward when the group is complete, rather than using the public lobby as an assumed waiting area.","Use the on-property wedding planner named in Fairmont’s materials as the source for the final private-event approach. Recheck the public directions and the booked-space instruction 14 days out, then confirm them again in the final update. A resort map can orient the group, but a named current instruction is what belongs in dispatch.","A Fairmont quote request should distinguish resort guests, off-property hotel riders, wedding-party movements, and end-of-night destinations. Add the contracted indoor or outdoor setting and state whether the public lobby route has been approved for the shuttle. That detail lets the reservations team price real movements instead of assuming every guest starts outside the resort."]}),c({path:"/guides/venues/sanctuary-camelback-mountain",name:"Sanctuary Camelback Mountain",address:"5700 East McDonald Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official wedding site describes mountainside indoor and outdoor settings, including lawns, terraces, a ballroom, and intimate villa options.",arrivalNote:"Sanctuary publishes its McDonald Drive address but does not name a public wedding-shuttle gate; use the event team's instructions for the booked space and arrival window.",hotelPlan:"Some guests may be staying in resort casitas or villas while others arrive from Scottsdale hotels, so identify who truly needs an off-property shuttle.",sourceLabel:"Sanctuary Camelback Mountain weddings",sourceUrl:"https://www.sanctuaryaz.com/weddings",secondarySource:{label:"Sanctuary contact and address",href:"https://www.sanctuaryaz.com/contact"},venueSpecific:["Sanctuary’s wedding materials describe lawns, terraces, a ballroom, and intimate villa options at the McDonald Drive property. Use the exact contracted setting in the vehicle notes because “Sanctuary” alone does not tell the venue team which guest path or arrival instruction applies to this wedding.","Count resort guests and off-property riders separately before selecting a vehicle for Sanctuary. A couple using a villa setting may have a smaller movement than a ballroom celebration, and some guests may already be on site. Capacity planning should follow the manifest for each wave, not a broad estimate based on the venue’s range of settings.","Paradise Valley and Scottsdale hotel pickups should be grouped by readiness and destination, while anyone already at Sanctuary remains off the inbound shuttle manifest unless a movement is specifically planned. Give each hotel one approved waiting point and keep the McDonald Drive venue arrival as the final instruction, not another place for guests to negotiate where to meet.","Sanctuary publishes 5700 East McDonald Drive but no permanent public wedding-shuttle gate. Ask the event team where the assigned vehicle should unload for the booked lawn, terrace, ballroom, or villa setting. Also ask whether the return pickup uses that same point, because arrival and late-evening traffic patterns may be handled differently.","When the wedding uses more than one Sanctuary setting, write whether guests walk between them or board for another movement. Do not infer the route or distance from a resort illustration. The wedding party may need a separate cue for portraits or preparation, while general guests should receive one simple ready time and venue-approved arrival instruction.","A Sanctuary return plan should separate guests staying on property from those returning to Paradise Valley or Scottsdale lodging. The early wave can serve family or guests leaving after dinner, while the final sweep follows the contracted event end. Each wave needs its own destination list and a venue-confirmed assembly point.","At the final planning review, repeat the booked Sanctuary setting, McDonald Drive address, arrival point, return point, and resort contact. If the ceremony moves between an outdoor and indoor option, ask whether the transportation instruction changes. Record only the answer that affects vehicle movement; do not burden the chauffeur with unrelated event details.","For a Sanctuary quote, include the contracted lawn, terrace, ballroom, or villa only as the venue identifies it, plus rider counts from each hotel and the number staying on property. Note any guest who needs extra boarding time. This creates a route-based request rather than a generic resort wedding inquiry."]}),c({path:"/guides/venues/grand-hyatt-scottsdale-resort",name:"Grand Hyatt Scottsdale Resort",address:"7500 East Doubletree Ranch Road, Scottsdale, Arizona 85258",venueFacts:"Hyatt identifies the property as Grand Hyatt Scottsdale Resort and describes renovated ballrooms plus indoor and outdoor function space.",arrivalNote:"Hyatt publishes the Doubletree Ranch Road address but not a public wedding-shuttle gate on its event page; the booked space and arrival point should be confirmed with the resort team.",hotelPlan:"The property itself may house many guests, so separate in-resort walkers from riders coming from other hotels, homes, or the airport.",sourceLabel:"Hyatt announcement of the Grand Hyatt Scottsdale Resort name and event spaces",sourceUrl:"https://newsroom.hyatt.com/2024november11GrandHyattScottsdale",venueSpecific:["Hyatt now identifies the property as Grand Hyatt Scottsdale Resort and publishes 7500 East Doubletree Ranch Road. Use that current name on every manifest, map pin, and chauffeur note; older planning documents may still contain the former resort name, so the transportation lead should replace it before details are distributed.","Grand Hyatt lists ballrooms, lawns, gardens, and other event settings, making the contracted space essential to capacity and timing discussions. Separate guests staying at the resort from those riding in from other locations, then choose vehicles for the actual waves. The full reception attendance is not a substitute for that movement-by-movement count.","Begin hotel-wave planning by removing Grand Hyatt guests who will not ride inbound, then group off-property Scottsdale or Paradise Valley lodging by exact address and ready time. If airport luggage remains with any arriving guest, identify that movement separately. A wedding shuttle should not discover at the first pickup that a local guest wave also carries travel bags.","The Doubletree Ranch Road address routes the vehicle to Grand Hyatt, but Hyatt’s event page does not publish a wedding-shuttle gate. Ask the resort team for the approved arrival tied to the booked ballroom, lawn, or garden. Record whether the same location is used after the reception and whether a vehicle may wait nearby.","If the Grand Hyatt ceremony and reception use different settings, ask whether guests walk between them and whether the wedding party moves on a separate schedule. Keep any vehicle transfer as an explicit itinerary line with a rider count. Do not assume that every change of event space creates a transportation need or that every guest follows the wedding party.","For the return, divide guests who stay at Grand Hyatt from riders returning to other hotels, homes, or an airport-area property. A resort guest should not occupy a seat simply because their name appears on the reception list. Label each outbound wave by destination and have the transportation lead confirm who has already returned to a room.","At 14 days, verify the current Grand Hyatt name, Doubletree Ranch Road address, contracted setting, and vehicle instructions with the resort contact. Remove the former property name from guest messages unless it is needed to clarify an old document. The final update should use one naming convention so guests and chauffeurs search for the same destination.","A Grand Hyatt quote request should state how many guests stay at the resort, which off-property hotels need service, whether the ceremony and reception use separate settings, and the final return destinations. Attach the resort’s approved vehicle approach. These specifics let the reservations team evaluate the schedule without relying on the former name or a generic resort entrance."]})],H={updatedAt:"2026-10-27",path:"/guides/scottsdale-bachelorette-weekend",title:"Scottsdale Bachelorette Party Weekend",description:"Plan a three-day Scottsdale bachelorette weekend with an Old Town crawl, published Sprinter pricing, airport transfers, and one mobile headquarters.",metaDescription:"A three-day plan: the Old Town crawl, group sizing and the nightly return",h1:"Scottsdale bachelorette party weekend: a practical 3-day itinerary",eyebrow:"Three-day Scottsdale itinerary · bachelorette and nightlife guide · guests 21+",intro:"Scottsdale Sprinters plans a strong Scottsdale bachelorette weekend with one main plan per day, one transportation lead, and enough open time for the group to reset. Style of trip: Old Town nightlife bachelorette weekend, for guests 21 and over. This itinerary keeps Old Town stops walkable, uses a Sprinter as the mobile headquarters for longer moves, and prices the shared ride from published rates.",fleetTable:!0,itinerary:[{day:"Day 1",title:"Arrive, settle in, and start with dinner",plan:"Consolidate airport arrivals, stock the house or hotel, leave recovery time, and use one dinner reservation as the first fixed point."},{day:"Day 2",title:"Pool time, reset, and Old Town crawl",plan:"Keep the morning flexible, set one group-ready deadline, and stage the Sprinter before the first Old Town stop."},{day:"Day 3",title:"Brunch, a lighter activity, and departures",plan:"Choose one low-friction group activity, confirm the pickup time, and split airport waves by flight time."}],crawlStops:[{number:1,name:"A booked dinner anchor in Old Town",note:"One confirmed meal reservation before the entertainment-district portion of the night; confirm the address, time and reservation name directly with the restaurant."},{number:2,name:"The Entertainment District blocks",note:"The late venues cluster within a few blocks of Scottsdale Road and Stetson Drive; confirm current entry, cover and reservation details with each one directly."},{number:3,name:"One main celebration stop",note:"Choose a single venue for the centre of the night rather than a list, and check its current event calendar and dress guidance directly."},{number:4,name:"A quieter regrouping block",note:"The Fifth Avenue and Marshall Way shopping streets sit a short walk from the district and work as a meeting point when a line is long."},{number:5,name:"The late pickup point",note:"A lawful meeting place the chauffeur can reach, agreed before anyone leaves the last venue and sent to the whole group in writing."}],sections:[{heading:"What is the best shape for a 3-day Scottsdale bachelorette weekend?",answer:"Build the weekend around 3 anchors—arrival dinner, one main Old Town celebration, and a relaxed farewell—then protect at least 2 open blocks for pool time, getting ready, meals, and recovery, because a minute-by-minute schedule usually breaks as soon as one flight or reservation shifts.",paragraphs:["Day 1 should feel easy. Group arriving flights into a small number of airport pickup windows, give everyone time to check in, and make dinner the only hard deadline. Put the address, reservation name, ready time, and clothing plan in one shared note. Guests who land late should have a clear way to join without holding the entire group at the airport.","Day 2 carries the biggest celebration. Keep the morning optional, choose one pool or daytime reservation if the group wants it, then create a real reset window before Old Town. The transportation plan begins at the house or hotel, not at the first bar. Everyone boards together with charged phones, identification, and the items they need for the full evening.","Day 3 works best at a slower tempo. Brunch and one flexible activity give the group a final shared memory without creating another complex transfer. Have everyone ready before the vehicle arrives and split airport departures by terminal timing rather than friendship groups. The person with the earliest flight should not wait through a late group brunch."]},{heading:"Why Scottsdale for a bachelorette weekend?",answer:"Scottsdale puts 3 things a bachelorette weekend needs within a short drive of each other: a walkable nightlife district in Old Town, resort pools for the slow afternoons, and desert scenery for the photos, so one chauffeured vehicle can carry the whole group between them in a single booking.",paragraphs:["Paradise Valley, North Scottsdale and central Phoenix are close enough to fold dinner, the night out and the ride home into the same trip.","The same vehicle can cover those legs without anyone driving or splitting the group into separate cars."]},{heading:"Where should you stay for a Scottsdale bachelorette?",answer:"Choose among 3 bases: Old Town Scottsdale for a weekend built around nights out, a resort in Paradise Valley or North Scottsdale for pool days and spa time, or a vacation rental for a big group that wants one shared house, and the base you pick sets how long each ride takes.",paragraphs:["Stay in Old Town Scottsdale when the weekend is built around nights out. You are close to the restaurants and the nightlife district, and short rides keep the hourly clock low.","Stay at a resort in Paradise Valley or North Scottsdale when the weekend is built around pool days and spa time. A chauffeured vehicle closes the distance to Old Town at night.","A vacation rental suits a big group that wants one shared house. When you book the ride, give the full address and any gate code or community entry instructions, and pick a single front-door meeting point.",I()]},{heading:"How does a Sprinter work as the weekend’s mobile headquarters?",answer:"A single Sprinter can serve as mobile headquarters for 8 to 16 guests by keeping the group on one departure clock, giving everyone the same pickup message, and creating a consistent regrouping point between the house, dinner, Old Town, and the final return without relying on several separate cars.",paragraphs:["“Mobile headquarters” means the transportation plan has one accountable schedule and one known vehicle; it does not mean the vehicle can wait anywhere or store unlimited belongings. The transportation lead keeps the manifest, confirms when everyone is aboard, and communicates changes to the reservations team. Guests receive the simple version: where to stand, when to be ready, and what return wave they chose.","Choose capacity from the fleet table, then discuss the real load. A nominal seat count does not describe dresses, coolers or mobility devices. The reservations team can help check the proposed vehicle against those details. For a nightlife-only movement, a party-oriented Sprinter may fit the mood; for airport transfers, the practical answer can be different.","The vehicle is most valuable on the longer or less walkable legs: airport to lodging, lodging to Old Town, a planned daytime destination, and the final ride home. Inside a compact Old Town crawl, walking between confirmed nearby stops can be simpler than repeatedly loading the group. The chauffeur should use only legal, currently available loading places."]},{heading:"What does a Scottsdale Sprinter cost per person?",answer:`For 13 guests sharing the ${a["ultra-luxury-party-sprinter-scottsdale"]} for 5 billed hours, the published ${d("ultra-luxury-party-sprinter-scottsdale")}-per-hour rate works out to about ${u("ultra-luxury-party-sprinter-scottsdale",5,13)} per person before tax for the shared ride; the live total depends on the selected vehicle, service duration, and confirmed itinerary.`,paragraphs:["The calculation is deliberately transparent: the published hourly rate is multiplied by 5 billed hours and divided by 13 riders. If fewer people split the same vehicle, the per-person amount rises; if the group chooses a different vehicle or service window, it changes. Use the fleet table as a planning comparison, then request a quote for the actual route.","Do not compare a group vehicle with a single app estimate shown before a surge, a stop, or a post-event pickup. The useful comparison includes how many separate cars the group would need, whether everyone departs together, and who is responsible for finding missing riders. A shared hourly plan buys coordination as well as seats.","The itinerary should separate airport service from the nightlife service when the timing or group size differs. A vehicle that fits the celebration may not be the best airport loadout. Send flight waves to the reservations team so each portion can be priced against the right vehicle rather than forcing one assumption across the entire weekend."]},{heading:"How much does a Scottsdale bachelorette weekend cost by group size?",answer:`For a 5-hour booking, Scottsdale Sprinters' published hourly rates work out to about ${l[0].each} per person for 8 guests, ${l[1].each} for 12, ${l[2].each} for 15, ${l[3].each} for 16 and ${l[4].each} for 25, before tax; the quote for your date is confirmed in writing.`,paragraphs:["Each row in the table pairs the group with one listed vehicle that seats everyone, then divides the published hourly rate times 5 hours by the number of riders. The shared ride is only one line of a weekend budget; venue cover, dinner and lodging sit outside it, and airport transfers are priced separately.","A group that lands between two sizes should price both. One extra seat of headroom often costs less per person than a tight fit, because the cost is split across more riders and nobody is left to arrange a second car."],table:{head:["Guests","Vehicle","Seats","Hourly rate","About per person for 5 hours"],rows:l.map(e=>[String(e.guests),e.name,String(e.seats),e.rate,e.each])}},{heading:"How does an Old Town bar crawl for 15 work?",answer:`Scottsdale Sprinters fits an Old Town bar crawl for 15 in the ${a["limo-sprinter-16-scottsdale"]}, which seats ${i["limo-sprinter-16-scottsdale"]}; at ${d("limo-sprinter-16-scottsdale")} per hour for 5 hours, that is about ${u("limo-sprinter-16-scottsdale",5,15)} per person before tax, so the shared ride stays simple, and every guest on a bar crawl must be 21 or older.`,paragraphs:[`The ${a["limo-sprinter-16-scottsdale"]} leaves room for a sixteenth guest. If the group prefers the ${a["ultra-luxury-party-sprinter-scottsdale"]}, which seats ${i["ultra-luxury-party-sprinter-scottsdale"]}, it is ${d("ultra-luxury-party-sprinter-scottsdale")} per hour, about ${u("ultra-luxury-party-sprinter-scottsdale",5,15)} per person for the same 5 hours. Send the final headcount to the reservations team and the vehicle is checked against it.`,"The Sprinter earns its hours on the legs between lodging, dinner and the Entertainment District, then again on the late return. Inside the district, walking between confirmed stops is often simpler than loading 15 people at every door. Agree one lawful late pickup point in writing before the group splits up.","Alcohol is allowed aboard for guests 21 and over, and venues check identification at the door. Anyone under 21 should have a separate plan for the night."]},{heading:"How should a practical Old Town crawl be sequenced?",answer:"Sequence the night in 3 moves—a booked dinner anchor, one main stop inside the Entertainment District, and a late pickup point the chauffeur can legally reach—then confirm reservations, dress rules, event programming, and entry conditions directly with each venue, because those conditions change without notice.",paragraphs:["The numbered route below is a planning sequence, not a promise of admission or a claim that every stop belongs in one night. A dinner reservation works as the meal anchor when booked directly. The late venues sit in the Entertainment District and are listed in Old Town Scottsdale’s official nightlife directory. No district claim or operating hours are assigned to any stop here.","Book the most important reservation first, then build around it. If the group cares about dinner or a particular evening’s programming, confirm that directly with the venue. Keep confirmation emails and the reservation name in the shared plan. A transportation booking does not create venue admission, skip a line, or override dress and identification requirements.","Designate a regrouping point before entering a loud venue. The group should know what happens if someone leaves early or cannot be reached. Do not ask a chauffeur to stop in an unapproved travel lane while the group decides. The transportation lead should call the movement only after guests are together and the driver confirms the legal pickup position."]},{heading:"How should the Old Town pickup and return be planned?",answer:"Use 2 written meeting points: a venue-confirmed arrival location and a separate late-night pickup location that the chauffeur can legally reach, then set one primary departure time plus a backup contact, because crowded streets and changing traffic controls make an improvised curbside search unreliable.",paragraphs:["Old Town is compact, but the entertainment district can be busy. The exact pickup point should be confirmed on the service day based on current traffic and venue instructions. This guide does not invent a club gate or claim a permanent shuttle lane. Guests should expect a short walk to a lawful meeting point if streets are restricted or congested.","Share a map pin only after the chauffeur or dispatch contact has confirmed it. A pin dropped by a guest from inside a building can land on an alley, patio, or wrong side of the block. The transportation lead should send the final location to the group and collect everyone there before calling the driver forward.","Choose the return rule before the night begins. If the group books one final departure, say clearly that leaving earlier requires a separate plan. If two waves are scheduled, assign riders in advance and record switches. The bride should never be the person counting heads on a crowded sidewalk while also trying to enjoy the celebration."]},{heading:"What should the group pack, assign, and confirm?",answer:"Give 1 person the master itinerary and assign 3 backups—lodging contact, reservation contact, and transportation contact—while every guest carries identification, a charged phone, the lodging address, and weather-appropriate basics, so one lost device or delayed guest does not stop the entire weekend plan.",paragraphs:["Keep the master itinerary short enough to use. It should show addresses, reservation names, ready times, departure times, and the transportation lead. Put optional activities in a separate section so guests can distinguish the fixed plan from suggestions. Avoid a long group-chat thread as the only source of truth; important information disappears quickly once travel begins.","For airport day, give the reservations team every flight wave and the real headcount. For nightlife, reduce what guests carry and confirm each venue’s current entry rules directly. Do not leave valuables or essential medication in a vehicle on the assumption that the same vehicle will remain in the same place all night.","Scottsdale conditions vary by season and time of day. Check an official forecast close to the weekend and plan water, sun protection, or a layer as appropriate. The group should also agree on a buddy system and a simple decision rule: no one changes venue alone without telling the transportation lead or their assigned buddy."]},{heading:"When should the weekend transportation be booked?",answer:"Availability varies by date and by vehicle, so no fixed lead time applies: work the manifest in 3 passes — confirm the flight waves once the group has booked flights, recheck lodging and venue details as they are fixed, then send the final passenger list 48 hours before service.",paragraphs:["Start with the pieces that are unlikely to change: travel dates, lodging, the main celebration night, estimated group size, and desired service window. The reservations team can recommend a fleet option from those facts. You do not need every brunch selected before asking, but you do need honest timing and a realistic pickup area.","Once flights are booked, collect them in a spreadsheet and group arrivals by a useful window. Confirm the exact lodging address, including unit or building instructions that the property permits you to share. Recheck every major venue reservation and current entry guidance. This is the point to decide whether one airport vehicle can serve everyone or separate waves are necessary.",`Forty-eight hours out, send a clean operational summary rather than forwarding the whole planning chat. Include named contacts, rider count, ready times, addresses, and the confirmed Old Town meeting plan. If something changes afterward, have one person notify the reservations team and wait for acknowledgement before telling the group the plan is final. ${b}`]},{heading:"What are the most common bachelorette transportation questions?",answer:"Most groups ask 4 things: whether one Sprinter can cover airport and nightlife service, how per-person pricing is calculated, where an Old Town pickup can happen, and how late changes are handled; the answers below keep those decisions tied to the real manifest and confirmed itinerary.",paragraphs:[]}],faqs:[{question:"Can one vehicle handle the whole weekend?",answer:"It can cover several scheduled movements, but airport timing, service gaps, and different group sizes may make separate bookings more practical. Share the complete itinerary with the reservations team."},{question:"Does the transportation reservation include club admission?",answer:"No. Venue reservations, admission, identification, dress rules, and event passes are separate. Confirm them directly with each official venue."},{question:"Can the group add stops during the night?",answer:"Ask the reservations team before service and route day-of requests through the transportation lead. A new stop must fit the booked time, legal access, and driver instructions."},{question:"Where can we be picked up at Phoenix Sky Harbor Airport?",answer:"Yes. Sprinter-class vehicles serve Phoenix Sky Harbor. Send each flight number and landing time to the reservations team. The Pink Hummer Limo does not do Sky Harbor pickups, so airport legs are quoted on a Sprinter or larger vehicle."},{question:"Can you pick us up at our Airbnb?",answer:"Yes. Send the full street address in writing, plus any gate code, community entry rule or parking note the host provides. Some private streets and communities restrict large vehicles, so the chauffeur may meet the group at the nearest lawful point, which is agreed before the night."},{question:"What can we add to a bachelorette ride?",answer:"Decorations, custom signs, a custom AI song, non-alcoholic refreshments and Fiji water. Ask the reservations team when you request the quote."},{question:"Do guests need to be 21 for the bar crawl?",answer:"Yes. Guests must be 21 or older, and venues check identification at the door."},{question:"Where does the Sprinter pick up in Old Town?",answer:"The exact lawful meeting point is confirmed for the service plan and current conditions. This guide intentionally does not promise a permanent curb or invented venue gate."}],links:[{href:"/experiences/bachelorette-party",label:"Bachelorette party transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:"Ultra Luxury Party Sprinter"},{href:"/fleet/pink-hummer-limo",label:a["pink-hummer-limo"]},{href:"/fleet/party-bus-28-scottsdale",label:a["party-bus-28-scottsdale"]},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport Sprinter service"},{href:"/pricing",label:"Hourly and per-person pricing"}],sources:[{label:"Old Town Scottsdale nightlife directory",href:"https://oldtownscottsdaleaz.com/eat-drink/nightlife/"}]};function w(e){const t=e.article?`${e.article} ${e.name}`:e.name;return{path:e.path,updatedAt:e.updatedAt,title:e.metaTitle??`${e.name} Transportation Guide | Scottsdale Sprinters`,description:`Plan ${e.name} group transportation with the official date status, published fleet capacities, hotel pickup, arrival, and post-event pickup guidance.`,metaDescription:"Official date status, hotel pickup, venue arrival and the post-event pickup plan",h1:e.h1??`${e.name} group transportation`,eyebrow:e.dateLine,intro:`A dependable ${e.name} ride from Scottsdale Sprinters begins with the official event information, a realistic rider count, and one transportation lead. This guide uses published organizer or venue facts, leaves unannounced details unguessed, and turns the day into a written pickup, arrival, communication and return plan.`,fleetTable:!0,sections:[{heading:`When is ${t}?`,answer:e.dateAnswer,paragraphs:["Use the official source linked below as the date authority. Artist schedules, participating teams, kickoff times, venue hours, and traffic instructions may arrive later than the date itself. Do not build a pickup plan around an unofficial calendar listing. The transportation lead should recheck the organizer page at booking, again as the date approaches, and on the service day.",e.eventSpecific[0],"Publishing early matters because a large-event route needs more than a car reservation. The group may still need admission passes, lodging, a meeting point, and agreement about who rides home. An article published ahead of the event gives planners time to compare vehicle sizes, collect guest commitments, and confirm current access rules without inventing details.","When a date or time remains unannounced, the quote request can still describe the expected city, group size, hotel area, and service pattern. Mark uncertain times as planning placeholders, not confirmed instructions. The reservations team can update the service window once the official organizer publishes the missing information."]},...e.gettingThere?[e.gettingThere]:[],{heading:`Which vehicle size fits a ${e.name} group?`,answer:`For ${t}, compare the published capacity bands from ${o[0].capacity} through ${o[o.length-1].capacity} passengers, then choose from the committed rider count and what the group will carry; the largest seat number is not automatically the best choice when people have permitted gear, accessibility needs, or hotel luggage.`,paragraphs:[`The fleet table uses current published information for each displayed name, maximum seated capacity, hourly rate, and minimum. A ${a["executive-sprinter-scottsdale"]} seats ${i["executive-sprinter-scottsdale"]}; a ${a["motorcoach-56"]} seats ${i["motorcoach-56"]}. Larger groups can use multiple coordinated vehicles when one vehicle does not fit the rider count or what guests will carry.`,"Count the riders for each direction. The outbound group may be larger than the return group, especially when some guests camp, stay near the venue, or leave with family. Give every return rider a specific vehicle or wave. “We will decide later” is not a useful manifest when a large event crowd is leaving at once.",e.eventSpecific[1],"Tell the reservations team about permitted personal items before choosing the vehicle. Event bag and chair rules belong to the organizer, and vehicle fit belongs to the operator. Something allowed into the venue may still consume meaningful cabin space. Keep aisles and exits clear, and never use an advertised seat count as a substitute for a real load review."]},{heading:`How should a group arrive at ${e.venue}?`,answer:`Plan 1 documented arrival route to ${e.venue}, with the chauffeur following current event staff, traffic control, and the organizer's published instructions; a saved gate name from an earlier event is not reliable enough for dispatch, so this guide uses only access details supported by an official source.`,paragraphs:[`${e.verifiedAccess} The operational plan should record the venue as ${e.venueAddress}, plus any event-specific permit, lot, or loading instruction supplied for the booked vehicle. If an organizer later publishes a different route, that current instruction replaces the general address.`,e.eventSpecific[2],"Build arrival buffer before the first activity the group cares about, not merely before the headline start. Loading riders, traffic control, security screening, and the walk from the approved unload area all take time. The vehicle cannot bypass public safety instructions, and the group should not ask to unload in a travel lane because the schedule ran tight.","Keep admission passes, identification, and allowed personal items ready before the door opens. The transportation lead counts riders as they leave and identifies the return meeting plan once more. Nobody should assume that the arrival position will remain the pickup position after the event; traffic plans can reverse or move during egress."]},{heading:`What should the ${e.name} itinerary include?`,answer:`Write 7 lines into the ${e.name} itinerary: guest ready time, vehicle departure, venue arrival target, primary contact, official address, post-event meeting instructions, and final roll time, then keep optional meals or gatherings in a separate section so riders can immediately see the commitments that affect transportation.`,paragraphs:[`${e.dayPlan} Turn that outline into clock times only after official hours or kickoff information is available. A useful schedule works backward from the desired arrival, adding expected loading and a conservative traffic allowance. Avoid publishing a universal drive time because origin, closures, day of week, and event operations all change it.`,e.eventSpecific[3],"The ready time is when guests are physically at the pickup point with everything they will take. It is not the time they begin leaving hotel rooms. The transportation lead should arrive earlier, check the manifest, and contact missing riders. Decide in advance who has authority to hold the vehicle and how long the schedule can absorb that hold.","Include one contingency sentence: if the group becomes separated, each rider follows the written meeting instruction and contacts the transportation lead. Do not create multiple competing pins during the event. A simple, approved plan is easier to execute when cellular service is busy and the surrounding streets are controlled."]},{heading:`How should pickup after ${t} work?`,answer:`Use 2 checkpoints after ${t}: the group first gathers at a pedestrian meeting place permitted by venue instructions, then the transportation lead confirms the vehicle’s active pickup point before anyone walks toward it, preventing riders from chasing a moving vehicle through controlled traffic or crowd flow.`,paragraphs:["The chauffeur may be directed away from the arrival location or held until traffic staff release a lane. That is normal large-event operations, not a reason for guests to enter a roadway. The lead stays with the group, keeps a headcount, and waits for a confirmed message about where and when to move.","Set expectations before arrival: the vehicle cannot stop wherever a phone pin lands, and an event's official traffic team controls access. Guests should wear appropriate footwear for the walk they can reasonably expect around a large venue and keep enough phone charge for post-event messages. Anyone leaving separately tells the transportation lead.",e.eventSpecific[4],"For multiple return waves, label vehicles and destinations clearly. A hotel shuttle and a local-home shuttle should not rely on guests recognizing a driver in a crowd. Use the vehicle name, lead name, and destination list. The final sweep verifies the manifest before departure rather than waiting on people who changed plans without notice."]},{heading:`How far ahead should ${e.name} transportation be reserved?`,answer:`Availability for ${t} varies by date and by vehicle, so no fixed lead time applies: request a current quote with the rider count, hotel area and service pattern, and the reservations team confirms in writing what is open across the published capacity bands from ${o[0].capacity} to ${o[o.length-1].capacity} passengers, updating it as official information is announced.`,paragraphs:["The first request needs the event, lodging or pickup area, likely passenger count, desired arrival, and return concept. A group does not need every attendee name to begin, but it should distinguish committed riders from possible riders. The reservations team can compare a single larger vehicle with several coordinated smaller options using current published capacities.","Once the group is committed, close the manifest and collect mobility needs, allowed gear, and destination choices. Confirm the official event status and make sure every rider has an admission plan independent of transportation. If the organizer has not announced an important detail, mark it open and assign one person to monitor the official source.",e.eventSpecific[5],"During the final 48 hours, verify addresses, contact numbers, service times, and current venue directions. Send one final summary to riders. If official instructions change on the day, the chauffeur follows traffic personnel and the transportation lead relays the update; the group should not treat an older screenshot as authority over current controls."]},{heading:`How is ${e.name} transportation priced per person?`,answer:`For 12 ${e.name} riders sharing the ${a["executive-sprinter-scottsdale"]} across 5 billed hours, the published ${d("executive-sprinter-scottsdale")}-per-hour rate is about ${u("executive-sprinter-scottsdale",5,12)} per person before tax for the complete shared ride; actual pricing changes with the vehicle, duration, itinerary, and confirmed service plan.`,paragraphs:["That example is arithmetic, not a flat event fare: hourly rate multiplied by billed hours, divided by riders. It gives a group a common basis for comparison while staying aligned with the published rate. If only ten people ride, divide across ten. If the group needs a larger vehicle or a longer service window, request the matching calculation.","A complete plan may include a continuous vehicle, separated inbound and outbound transfers, or several hotel waves. Each structure uses time differently. Describe the actual service pattern when asking for a quote instead of requesting “round trip” and leaving a many-hour gap unexplained. The reservations team can then price the schedule that the group expects.",e.eventSpecific[6],"Per-person math is most useful after the rider list stabilizes. Name one person to collect shares and one person to manage the manifest; they can be the same person, but neither job should fall to the chauffeur. The transportation service moves the confirmed group while the lead owns internal guest decisions."]},{heading:`What are the most common ${e.name} transportation questions?`,answer:`Most ${e.name} groups need 4 answers before booking: the official date status, the number of committed riders, the venue's current vehicle instructions, and the return meeting process; the FAQ below addresses those points without promising an unpublished time, access route, parking privilege, or gate.`,paragraphs:[]}],faqs:[...e.faqs??[],{question:`Does a transportation booking include ${e.name} admission?`,answer:"No. Admission passes, wristbands, parking credentials, and venue entry are separate. Purchase and verify them only through the event’s official channels."},{question:"Can the vehicle wait next to the venue?",answer:"Only where current event operations permit it. Staging and pickup instructions can change, so the chauffeur follows venue staff and the transportation lead shares the confirmed meeting plan."},{question:"Can a group bring chairs, coolers, or bags?",answer:"Check the organizer’s current allowed-items policy first, then tell the reservations team exactly what the group will carry so vehicle fit can be reviewed."},{question:"What if the official event time changes?",answer:"Have the transportation lead contact the reservations team promptly. A revised service window is not assumed until the change is acknowledged and the updated plan is confirmed."}],links:[...e.links,{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:[e.source,e.accessSource,...e.additionalSources??[]]}}const R=[w({updatedAt:"2026-09-26",path:"/guides/country-thunder-transportation",name:"Country Thunder Arizona",titleName:"Country Thunder Arizona 2027",dateLine:"Official dates: April 8–11, 2027",dateAnswer:"Country Thunder Arizona is officially scheduled for April 8–11, 2027—4 festival days at AZ Talio Ranch in Florence—and the organizer says 2027 hours will be announced closer to the festival, so build transportation around the published dates but wait for official daily times before locking departures.",venue:"AZ Talio Ranch",venueAddress:"20585 East Water Way, Florence, Arizona 85132",verifiedAccess:"Country Thunder’s official information page publishes the ranch address, tells fans to buy parking in advance because onsite parking is limited and not guaranteed on the day, names Stagecoach Express Shuttles as its partner shuttle from Mesa and Apache Junction, and says Uber and Lyft are available in Florence, with pre-booking recommended.",dayPlan:"For a festival day, the outline is hotel pickup, comfort stop if scheduled, venue arrival, a written post-show regrouping process, and the return to the named lodging stops.",gettingThere:{heading:"Where do you park at Country Thunder Arizona, and how do rideshares and shuttles work?",answer:"Country Thunder Arizona tells fans to buy parking in advance because onsite parking at AZ Talio Ranch, 20585 E Water Way in Florence, is limited and not guaranteed on the day; its partner shuttle runs from Mesa and Apache Junction, Uber and Lyft serve Florence with pre-booking advised, and no lot allows tailgating.",paragraphs:["The festival sells its parking online ahead of time. The passes it lists include weekend day parking, a weekend overnight lot, one extra-vehicle pass per campsite, and a camper drop-off pass for an RV delivered by someone without festival admission. Accessible spaces sit at the front of the reserved parking area, across from the reserved entrance; tell the front-gate staff on arrival.","Its parking-lot rules ban tailgating in every lot, reserved, day, ADA, glamping, staff and overnight alike, and ban cooking, grills, amplified sound and drinking games there too. Only vehicles accredited for a lot may enter it, and a vehicle without the right credential can be towed. A group that planned a lot party should plan it for the drive instead.","For rideshare, the festival says Uber and Lyft are available in Florence and recommends pre-booking a ride to guarantee a driver. As of September 24, 2026, its information page names no rideshare zone at the ranch and no drop-off lane for limousines, party buses or charters, so a chauffeur unloads where festival traffic staff direct and follows any instruction the festival publishes later.","The festival’s partner shuttle, Stagecoach Express Shuttles, picks up and drops off in Mesa at 240 West Baseline Road and in Apache Junction at 185 West Apache Trail, booked by phone. It does not start in Scottsdale. From a Scottsdale hotel or home, the ranch is about 63 miles and 66 minutes from Old Town by Google Directions, without festival traffic.","With a chauffeured ride, nobody in the group buys a parking pass or drives home after the headliner. The vehicle picks everyone up at the hotel or home and unloads where staff direct, and when it is booked by the hour the same vehicle brings the group back after the last set. Each festival day is its own booking."]},source:{label:"Country Thunder Arizona official 2027 event page",href:"https://www.countrythunder.com/az"},accessSource:{label:"Country Thunder Arizona official festival information",href:"https://www.countrythunder.com/az-info"},additionalSources:[{label:"Country Thunder festival policies: bags and parking lots",href:"https://www.countrythunder.com/policies"},{label:"Country Thunder Arizona 2027 lineup page",href:"https://www.countrythunder.com/az-lineup"}],links:[{href:"/experiences/country-thunder",label:"Country Thunder transportation experience"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/party-bus-28-scottsdale",label:"28-passenger party bus"},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:"Ultra Luxury Party Sprinter"},{href:"/guides/phoenix-concerts-2026-2027",label:"Phoenix concerts and festivals, 2026–27"}],faqs:[{question:"Where is Country Thunder Arizona held?",answer:"At AZ Talio Ranch, 20585 E Water Way, Florence, Arizona 85132. By Google Directions it is about 63 miles and 66 minutes from Old Town Scottsdale, and about 73 miles and 75 minutes from the Fairmont Scottsdale Princess, without festival traffic."},{question:"What are the Country Thunder Arizona 2027 dates?",answer:"Four days: Thursday, April 8; Friday, April 9; Saturday, April 10; and Sunday, April 11, 2027. The festival says the 2027 hours are announced closer to the festival, and its full lineup is still to come."},{question:"Who is performing at Country Thunder Arizona 2027?",answer:"The 2027 lineup is not announced yet. As of September 26, 2026, the festival’s lineup page says the full lineup is coming soon and teases a Sunday, April 11 headliner without naming the artist, and it notes that artists and schedule can change without notice."},{question:"What is Country Thunder Arizona?",answer:"A four-day country music festival with camping at AZ Talio Ranch in Florence, run by Country Thunder, which also holds festivals in Wisconsin and Saskatchewan. It runs rain or shine, and the festival guarantees admission bought only from Country Thunder or its official partner."},{question:"What time do the gates open at Country Thunder Arizona?",answer:"The 2027 hours are announced closer to the festival. Last year the concert bowl opened at 3 p.m. on Thursday, 1 p.m. on Friday and Saturday, and 1:30 p.m. on Sunday, and the front gate was open from 9 a.m. to 10 p.m.; anyone arriving after it closed could not drive onto the grounds."},{question:"Can Uber or Lyft drop off at Country Thunder Arizona?",answer:"Uber and Lyft are available in Florence, and the festival recommends pre-booking a ride to guarantee a driver. It names no rideshare zone at the ranch, so drivers follow festival traffic staff. A chauffeured ride booked by the hour covers both ways: the same vehicle takes the group there and brings it home."},{question:"Is there a shuttle to Country Thunder Arizona from Scottsdale?",answer:"The festival’s partner shuttle, Stagecoach Express Shuttles, runs from Mesa and Apache Junction, not Scottsdale. From Scottsdale, a private ride starts at your hotel or home and unloads where festival traffic staff direct; booked by the hour, it brings the group back after the last set."},{question:"Can single-day guests use the campgrounds?",answer:"No. The festival says the campgrounds need full-event admission and that single-day holders do not have access. A campsite is sold for the whole festival, never by the night, and comes with two weekend general admission passes and parking for one vehicle."},{question:"Can we book a ride for all four days?",answer:"Yes, one booking per day. Each festival day is its own ride, with its own pickup time, riders and return, so a group can book Thursday and Saturday only, or all four. The price of each day is shown before you pay."},{question:"Is tailgating allowed at Country Thunder Arizona?",answer:"No. The festival’s parking-lot rules ban tailgating in every lot, along with cooking, grills, amplified sound and drinking games. The pre-party can ride with you instead: our party vehicles carry wet bars, lounge lighting and big sound for the hour-long drive to Florence."},{question:"What can we bring into the concert bowl?",answer:"Clear bags up to 14 by 14 inches, a one-gallon freezer bag or a small clutch; soft lawn chairs without canopies; and one unopened bottle of water per person. Outside food and drinks, coolers, backpacks, glass and umbrellas stay out, and the festival is cashless."}],eventSpecific:["Country Thunder publishes four festival dates but says the 2027 hours will be announced closer to the event. Keep each daily departure in draft until those hours appear, and do not assume that one day’s timing applies to the next. The transportation lead should recheck the Arizona event page for every day the group plans to attend.","A Country Thunder group may carry only items allowed by the festival: into the concert bowl, clear bags up to 14 by 14 inches, soft lawn chairs without canopies and one sealed bottle of water per person, with coolers, backpacks and outside food left behind. Anything the group brings still consumes vehicle space, so count it before selecting from the published capacities. A vehicle that fits riders for a Scottsdale night out may need a different load review for a camping weekend in Florence.","The official destination is AZ Talio Ranch at 20585 East Water Way in Florence, and the festival warns that onsite parking is limited. That statement does not create a commercial drop-off privilege, and the festival’s lot rules admit only vehicles accredited for each lot. Send the current event instructions to the reservations team, document the assigned arrival process, and follow staff direction when the vehicle reaches the ranch.","A four-day Country Thunder plan should be written as four separate service days even if the same group attends each one: Thursday, April 8; Friday, April 9; Saturday, April 10; and Sunday, April 11, 2027. Rider counts, readiness, permitted items, and return choices can change by day. Label every schedule with the correct date so an unannounced daily hour can be inserted later without silently changing another day’s plan.","After each Country Thunder day, the group gathers at one agreed meeting point before anyone walks toward the vehicle, and the lead sends one confirmed message about where the chauffeur is waiting. Last year the front gate was open from 9 a.m. to 10 p.m., and the festival said anyone arriving after it closed could not drive onto the grounds, so plan the late pickup before the headliner starts, not after it ends.","At the 14-day review, check whether Country Thunder has published the 2027 daily hours, the lineup, and any updated transportation or allowed-items information. If a detail remains unannounced, leave it clearly open and tell riders when it will be checked again. The official Arizona page, not a recycled itinerary from an earlier festival, controls the planning facts.","Price each Country Thunder service window from the lodging pickup through the confirmed return plan. Florence is about 66 minutes from Old Town each way by Google Directions, so a festival day booked by the hour runs well past a short example: our ready-made festival days run 10 to 12 hours door to door. A group attending more than one day books each day on its own."]}),w({updatedAt:"2026-09-24",path:"/guides/fiesta-bowl-transportation",name:"Fiesta Bowl",article:"the",titleName:"Fiesta Bowl 2026-27",metaTitle:"Fiesta Bowl 2026: Parking & Parade",h1:"Fiesta Bowl 2026: parking, the parade and getting there",dateLine:"Official date: December 30, 2026",dateAnswer:"The 2026-27 Vrbo Fiesta Bowl is the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium in Glendale, so planners can anchor the service date now and should recheck the official page before confirming pickup times.",venue:"State Farm Stadium",venueAddress:"1 Cardinals Drive, Glendale, Arizona 85305",verifiedAccess:"The official 2026-27 Fiesta Bowl parking map and State Farm Stadium’s directions page both identify the Black Lot for rideshare. That published rideshare point is a planning reference, not a commercial-vehicle assignment; a charter drop-off for this game is announced closer to the date, and traffic staff remain controlling.",dayPlan:"For game day, the outline is hotel pickup, an optional pregame stop only if scheduled, arrival ahead of the 5:30 p.m. Arizona kickoff, a security and admission buffer, a postgame pedestrian regrouping point, and the confirmed vehicle pickup.",source:{label:"College Football Playoff Fiesta Bowl schedule",href:"https://collegefootballplayoff.com/sports/2021/9/7/fiesta-bowl"},accessSource:{label:"State Farm Stadium directions and parking",href:"https://www.statefarmstadium.com/plan-your-visit/directions-parking"},additionalSources:[{label:"Fiesta Sports Foundation 2026-27 CFP dates",href:"https://www.fiestasportsfoundation.org/news/2026/7/9/vrbo-fiesta-bowl-announces-dates-to-host-college-football-playoff-matchups-through-2032.aspx"},{label:"Fiesta Sports Foundation 2026-27 parking map",href:"https://www.fiestasportsfoundation.org/documents/2026/8/14/26-27_VFB_Parking_Map_FINAL.pdf"},{label:"Fiesta Sports Foundation Fiesta Bowl Parade",href:"https://www.fiestasportsfoundation.org/sports/2019/10/22/fiesta-bowl-parade.aspx"}],links:[{href:"/services/scottsdale-executive-minibus-group-shuttle",label:"Scottsdale group shuttle service"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter rental"},{href:"/fleet/executive-mini-bus-26-scottsdale",label:"24-passenger mini bus"},{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking guide"}],faqs:[{question:"Where is the Fiesta Bowl played?",answer:"At State Farm Stadium, 1 Cardinals Drive, Glendale, Arizona 85305. The 2026-27 game is the College Football Playoff quarterfinal."},{question:"What time does the Fiesta Bowl start?",answer:"5:30 p.m. Arizona time on Wednesday, December 30, 2026, the only College Football Playoff game that day. The College Football Playoff lists the same kickoff as 7:30 p.m. Eastern, because Arizona does not observe daylight saving time."},{question:"Where is the best place to park for the Fiesta Bowl?",answer:"The official 2026-27 parking map lists the West, North and East Preferred lots; the East Lot, Lot F and oversized parking; the West Lot, W2, the Great Lawn and the Yellow Lot; and the Black and Blue Lots, on game day only. Last season the lots opened at 11:30 a.m. and closed one hour after the game; this season’s times are announced closer to the date. With a chauffeured ride, nobody in the group parks."},{question:"Where do I buy Fiesta Bowl parking?",answer:"Parking passes are sold through the Fiesta Sports Foundation’s official parking link (SeatGeek), and State Farm Stadium’s lots take cards only."},{question:"How do I buy seats for the Fiesta Bowl?",answer:"From the Fiesta Sports Foundation, which runs the bowl: call 480.350.0911 or use its official website. A ride booking does not include game admission or a parking pass."},{question:"When is the Fiesta Bowl Parade?",answer:"Saturday, January 2, 2027, starting at 10 a.m. It is the 54th annual parade, admission is free, and it comes after the bowl games, not before."},{question:"Where does the Fiesta Bowl Parade go?",answer:"It is a 1.5-mile march through Central Phoenix, starting at North Central Avenue and Montebello Avenue, Phoenix 85012. The full 2027 route, grandstands and street closures are announced closer to the date."},{question:"Can we book a ride to the Fiesta Bowl Parade?",answer:"Yes, as its own ride on Saturday morning. Your chauffeur picks the group up at the hotel or home, drops everyone near the start at North Central Avenue and Montebello Avenue where police and event staff direct, and brings the group back when you are done."}],eventSpecific:["Fiesta Sports Foundation schedules this game as the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium. The College Football Playoff lists that same kickoff as 7:30 p.m. ET, because Arizona does not observe daylight saving time. Recheck both official pages if the organizer updates event information.","A Fiesta Bowl group usually needs one count for the stadium arrival and another for the return. Remove anyone using a separate postgame plan before assigning seats, and ask about mobility devices or personal items that affect fit. The vehicle choice should follow those confirmed movements, not the number of people included in a broader game-day gathering.","The official 2026-27 parking map places rideshare on the Black Lot, and the stadium directions page also names the Black Lot south of the stadium for rideshare and family-or-friend pickup. A limo or charter drop-off for this game is announced closer to the date. Use the Black Lot as rideshare orientation until the reservations team confirms the instruction for the booked vehicle.","Build the December 30 itinerary backward from the 5:30 p.m. Arizona kickoff at 1 Cardinals Drive in Glendale. If the group also wants the parade, schedule it as its own service: Saturday, January 2, 2027, at 10 a.m., starting at Central and Montebello in Phoenix, after the game. The 2027 parade route, grandstands, and street closures are announced closer to the date.","Postgame traffic at State Farm Stadium can be directed differently from arrival, so the lead should not send the group toward the Black Lot until the active pickup instruction is confirmed. Assemble first in a safe pedestrian place permitted by venue guidance, complete the headcount, and move only after the vehicle location and route are understood.","Before the Fiesta Bowl, confirm the December 30 date, the 5:30 p.m. Arizona kickoff, hotel addresses, the rider list, and the 2026-27 parking map. During the final 48 hours, recheck the Fiesta Sports Foundation and stadium pages. Live direction from stadium staff takes precedence over a saved map. January 2 parade closures are announced closer to the date.","A Fiesta Bowl quote should state whether the vehicle remains with the group, performs separate inbound and outbound transfers, or serves more than one hotel wave. Price examples based on five hours are comparisons only; the written quote must reflect the December 30 schedule, confirmed stadium access, rider count, and actual time requested."]})],G=[H,...L,...R];function B(e){return{path:e.path,title:e.h1,metaTitle:e.title,description:e.description,intro:e.intro,metaDescription:e.metaDescription,lastUpdated:e.updatedAt??g,lastUpdatedLabel:y(e.updatedAt??g),sections:e.sections.map(t=>({question:t.heading,answer:t.answer,paragraphs:[...t.paragraphs,...t.bullets??[]],...t.table?{table:t.table}:{}})),faqs:e.faqs,links:e.links,sources:e.sources,eyebrow:e.eyebrow,fleetRows:e.fleetTable?o:void 0,itinerary:e.itinerary,crawlStops:e.crawlStops}}const S=G.map(B);function T(e){const t=S.find(n=>n.path===e);if(!t)throw new Error(`[guides] Missing P3 guide: ${e}`);return t}const A=T("/guides/fiesta-bowl-transportation"),F=T("/guides/country-thunder-transportation"),V=Object.freeze(Object.defineProperty({__proto__:null,COUNTRY_THUNDER_GUIDE:F,FIESTA_BOWL_GUIDE:A,P3_HIJ_GUIDES:S,guideUpdatedLabel:y},Symbol.toStringTag,{value:"Module"})),j=Object.freeze(Object.defineProperty({__proto__:null,default:F},Symbol.toStringTag,{value:"Module"})),Y=Object.freeze(Object.defineProperty({__proto__:null,default:A},Symbol.toStringTag,{value:"Module"}));export{F as C,A as F,S as P,j as c,Y as f,V as s};
